-- Affiliation related-org guard (oxjob #1832, generated by #1832 work/guard/build_guard_sql.py from names_u.py sha a2202cd966ea).
-- Rule (charter "What 'right' means"; Kyle 26 Oct): a ROR-related organization never brings the university. On strings the
-- matcher answered in the last 3 days that link a university U and an organization ROR lists as related to U, drop U when
-- the string names U only inside the related record's own name or inside a hospital phrase (names_u classes inside_linked,
-- hosp_univ, hosp_uname, hosp_dutch: judged 655/665 right on a fresh blind draw, 26 Oct). Same mechanics as patch layer 7.
-- Until the matcher's teacher is retrained (#1832 PLAN step 4). Revert: pause this job; undo a day with the patches rows
-- (basis related_org_daily:*): MERGE before_ids back where institution_ids = after_ids.

CREATE OR REPLACE FUNCTION openalex.institutions.affiliation_names_u(s STRING, u_names ARRAY<STRING>, u_acr ARRAY<STRING>, desc_names ARRAY<STRING>,
                               mask_names ARRAY<STRING>, u_places ARRAY<STRING>)
RETURNS STRING LANGUAGE PYTHON DETERMINISTIC
COMMENT 'oxjob #1832 names_u v7 (sha a2202cd966ea): does an affiliation string name university U? keep:<why> or drop:<class>'
AS $$
import re
import unicodedata

UNIV = (r"(?:univ\w*|un\w{0,3}ers\w*|uniwersytet\w*|egyetem\w*|yliopist\w*|hochschule\w*|hogeschool\w*|daigaku|politec\w*|"
        r"polytech\w*|vidyapee?th\w*|vidyapith\w*|vishwa\w*|vidyalaya\w*|akademi\w*|academ\w*)")
UNIT = (r"(?:school|schools|college|faculty|faculties|fakultat\w*|faculte\w*|faculteit\w*|facultad\w*|facolta|"
        r"faculdade\w*|wydzial\w*|institute|institutes|institut|instituut|instituto|istituto|department|dept|"
        r"departement|departamento|dipartimento|abteilung|division|graduate|laborator\w*|lab|labs|institutions)")
FACULTY = re.compile(r"\b(?:faculty|faculties|fakultat\w*|fakultet\w*|faculte\w*|faculteit\w*|facultad\w*|facolta|faculdade\w*|"
                     r"wydzial\w*|school|schools|college of medicine|medical college|college of physicians|dipartimento|graduate school)\b")
HOSPW = (r"(?:hospital|hospitals|hospitalet|klinikum|kliniken|klinik|clinic|clinics|clinica|hopital|hopitaux|"
         r"ospedale|ziekenhuis|spital|krankenhaus|sjukhus\w*|sykehus\w*|sygehus\w*)")
HOSP = [
    ("compound",  # Universitatsklinikum, Universitatsspital, Universitatsmedizin, universitetssjukhuset, University Medicine
     r"\buniversit\w*?[\s-]*(?:kinder)?(?:klinik\w*|spital\w*|krankenhaus\w*|medizin\w*|sjukhus\w*|sjukehus\w*|"
     r"sykehus\w*|sygehus\w*|ziekenhuis\w*)"),
    ("univ",  # University Hospital(s), X University Medical Center, University of X Hospital, University Health Network
     r"\buniversit\w* (?:of [\w'.]+ )?(?:hospital|hospitals|clinics?)\b|\buniversit\w* (?:medical cent(?:er|re)s?|"
     r"health (?:system|network|care)|healthcare)\b"),
    ("of_univ",  # Hospital of the University of X, Klinikum der Universitat X, Affiliated Hospital of X University
     r"\b" + HOSPW + r"\b[^,\x3b()|]{0,40}?\b(?:of the|of|de la|de l|de|du|des|della|dell|di|at the|at)\s+"
     r"(?:\w+\s+){0,2}?universit\w*"),
    ("romance", r"\b(?:centre|center|centro) hospitali?er\w* universit\w*|\bhopita(?:l|ux) universitaires?\b|"
                r"\bhospital(?:es)? (?:clinico )?universitari\w*|\b(?:azienda )?ospedal\w*[\s-]+universitari\w*|"
                r"\bpoliclinico universitario\b"),
    ("dutch", r"\buniversitair (?:medisch cent\w*|ziekenhuis\w*)"),
]
HOSP_RE = [(k, re.compile(p, re.I)) for k, p in HOSP]
STOP = set("""university universitat universitaet universite universiteit universidad universidade universita
universitet universiteti uniwersytet universitatea univerzita egyetem yliopisto hochschule fachhochschule hogeschool
college school institute institut instituto istituto academy akademie of the and for und und der die das des de del
della degli dei di du la le les van von zu den het en et y e a in at medical medicine medizinische medica medicina
medicale technical technische technology technological technologie tecnologica tecnica sciences science scientific
health applied research state national federal royal central international polytechnic polytechnical politecnica
politecnico catholic free freie open normal agricultural pedagogical studies graduate city metropolitan south north
east west southern northern eastern western new saint sankt santa san nacional estadual autonoma autonomous libre
public private regional general hospital center centre clinic campus faculty department system systems foundation
""".split())
SEP = re.compile(r"[,\x3b()\[\]/|:]+|\s-\s|\s–\s")


def fold(x):
    x = unicodedata.normalize("NFKD", x or "")
    x = "".join(c for c in x if not unicodedata.combining(c)).replace("ß", "ss").replace("ø", "o").replace("æ", "ae").replace("ı", "i").replace("ł", "l").replace("đ", "d")
    x = re.sub(r"[-‐‑–—_]+", " ", x)
    return re.sub(r"\s+", " ", x).strip()


def _wb(name, loose_right=False):
    """Whole-word pattern for a folded name (boundaries only where the name starts/ends with a letter or digit).
    loose_right: no boundary after the name (long names glued to the next word: 'University of CopenhagenCopenhagen')."""
    p = re.escape(name)
    if name[:1].isalnum():
        p = r"(?<![a-z0-9])" + p
    if name[-1:].isalnum() and not loose_right:
        p = p + r"(?![a-z0-9])"
    return p


def _lev1(a, b):
    """True when a and b are within one edit (insert, delete, substitute, adjacent swap)."""
    if a == b:
        return True
    la, lb = len(a), len(b)
    if abs(la - lb) > 1:
        return False
    if la == lb:
        d = [i for i in range(la) if a[i] != b[i]]
        return len(d) == 1 or (len(d) == 2 and d[1] == d[0] + 1 and a[d[0]] == b[d[1]] and a[d[1]] == b[d[0]])
    if la > lb:
        a, b = b, a
    return any(b[:i] + b[i + 1:] == a for i in range(len(b)))


def _core(u_names):
    toks = set()
    for n in u_names:
        for t in re.findall(r"[a-z0-9]+", fold(n).lower()):
            if len(t) >= 4 and t not in STOP and not t.isdigit():
                toks.add(t)
    return toks


def _core_hit(w, core):
    """exact core word\x3b or a word that starts with a core word of 6+ letters (glued: 'copenhagencopenhagen')\x3b or a typo."""
    if w in core:
        return "hit"
    for c in core:
        if len(c) >= 6 and (w.startswith(c) or (len(w) >= 6 and _lev1(w, c))):
            return "hit" if w.startswith(c) else "typo"
    return None


def _keep(t, u_names, u_acr, desc_names, core, t_case, distinct=(), city=None):
    """t: folded lower-case text (possibly masked)\x3b t_case: same text before lower-casing (for short acronyms).
    distinct: U's name words that are neither its city/region/country nor part of a linked hospital's name ('harvard',
    not 'utrecht')\x3b one of them alone in the text keeps U ('Harvard Radiation Oncology Program', 'Harvard Med Sch')."""
    for n in u_names:
        if len(n) >= 4 and n in t and re.search(_wb(n, loose_right=len(n) >= 12), t):  # substring test first
            return "u_name"
    for a in u_acr:
        if len(a) <= 3:
            if re.search(r"(?<![A-Za-z0-9])" + re.escape(a.upper()) + r"(?![A-Za-z0-9])", t_case):
                return "u_acr"
        elif a in t and re.search(_wb(a), t):
            return "u_acr"
    for n in desc_names:
        if len(n) >= 5 and n in t and re.search(_wb(n), t):
            return "desc"
    for seg in SEP.split(t):
        words = re.findall(r"[a-z0-9]+", seg)
        hits = [h for h in (_core_hit(w, core) for w in words) if h]
        if not hits:
            continue
        sfx = "" if "hit" in hits else "_typo"
        if re.search(r"\b" + UNIV + r"\b", seg):
            return "univ_core" + sfx
        if re.search(r"\b" + UNIT + r"\b", seg):
            return "unit_core" + sfx
    if FACULTY.search(t):
        return "faculty"  # a faculty or school of an institution the string names: the unit rule (judged 26 Oct)
    if city and re.search(r"\b" + UNIV + r"\b", t):
        return "univ_city"  # "University Department of X, <City>": the city's university (charter, 25-26 Sep)
    if distinct:
        for w in re.findall(r"[a-z0-9]+", t):
            if w in distinct or any(len(c) >= 6 and len(w) >= 6 and _lev1(w, c) for c in distinct):
                return "core_only"
    return None


def _mask(tc, names):
    """Replace whole-word occurrences of each name (longest first) with ' | '. tc is case-preserved folded text."""
    low = tc.lower()
    for n in sorted(set(names), key=len, reverse=True):
        if n.lower() not in low:  # substring test first: regex only on a hit
            continue
        if len(n) <= 3:
            p = r"(?<![A-Za-z0-9])" + re.escape(n.upper()) + r"(?![A-Za-z0-9])"
            tc = re.sub(p, " | ", tc)
        else:
            tc = re.sub(_wb(n), " | ", tc, flags=re.I)
        low = tc.lower()
    return tc


EMAIL = re.compile(r"\S+@\S+|(?:https?://|www\.)\S+|\[email[^\]]*\]", re.I)
HOSPNAME = re.compile(r"hospital|medical cent|medisch|klinik|clinic|spital|health|\bmc\b|umc|medicine|medizin|ziekenhuis|"
                      r"sjukhus|sykehus|sygehus|hopita|ospedal|policlin|infirmary|nhs", re.I)


def names_u(s, u_names, u_acr, desc_names, mask_names, u_places=None):
    """Verdict on the string\x3b when it says drop, also try the string with glued words split
    ("CopenhagenCopenhagen", "HospitalSchool of MedicineZhejiang University") and keep if that keeps."""
    s = EMAIL.sub(" ", s or "")  # an email address or URL never names an institution
    s = re.sub(r"#\{(\d{2,4})\}", lambda m: chr(int(m.group(1))), s)  # "G #{246}teborg"
    s = re.sub(r"\s?\u00a8\s?", "", s)  # "Mu \u00a8nster"
    s = re.sub(r"(\d)([A-Za-z])", r"\1 \2", s)  # superscript digits glued on: "16University of Arizona"
    s = re.sub(r"([a-z])- ([a-z])", r"\1\2", s)  # line-break hyphenation: "Fac- ulty of Medicine"
    s = re.sub(r"\b((?:[A-Za-z]\.){2,})", lambda m: m.group(1).replace(".", "") + " ", s)  # "K.U.LEUVEN"
    v = _names_u(s, u_names, u_acr, desc_names, mask_names, u_places)
    if v.startswith("drop:"):
        s2 = re.sub(r"([A-Z]{2,})([A-Z][a-z]{2,})", r"\1 \2", re.sub(r"([a-z]{2})([A-Z][a-z])", r"\1 \2", s))
        if s2 != s:
            v2 = _names_u(s2, u_names, u_acr, desc_names, mask_names, u_places)
            if v2.startswith("keep:"):
                return v2 + "_split"
    return v


def _names_u(s, u_names, u_acr, desc_names, mask_names, u_places):
    u_names = [fold(n).lower() for n in (u_names or []) if n]
    u_acr = [fold(a).lower() for a in (u_acr or []) if a]
    desc_names = [fold(n).lower() for n in (desc_names or []) if n]
    core = _core(u_names)
    raw = fold(s)
    # never mask a name that is one of U's own names or sits inside one
    mask = [SEP.split(fold(n))[0].strip() for n in (mask_names or []) if n]
    mask = [m for m in mask if (len(m) >= 5 or (len(m) >= 2 and m.isalnum())) and not any(m.lower() in un for un in u_names)]
    placeish = {w for p in (u_places or []) if p for w in re.findall(r"[a-z0-9]+", fold(p).lower())}
    hosp_words = {w for m in mask if HOSPNAME.search(m) for w in re.findall(r"[a-z0-9]+", m.lower())}
    distinct = {c for c in core if len(c) >= 5 and c not in placeish
                and not any(w == c or w.startswith(c) for w in hosp_words)}
    city = fold(u_places[0]).lower() if u_places and u_places[0] and len(u_places[0]) >= 4 else None
    city = city if city and re.search(_wb(city), raw.lower()) else None  # the city counts wherever it sits in the string
    us = any(p and fold(p).lower() == "united states" for p in (u_places or []))
    acr_set = set(u_acr)
    mask = [m for m in mask if m.lower() not in acr_set]  # never mask one of U's own acronyms
    if _keep(raw.lower(), u_names, u_acr, desc_names, core, raw, distinct, city) is None:
        return "drop:absent"
    t = _mask(raw, mask)
    if _keep(t.lower(), u_names, u_acr, desc_names, core, t, distinct, city) is None:
        return "drop:inside_linked"
    if FACULTY.search(t.lower()):
        return "keep:faculty"  # checked before hospital phrases are masked ("Zhongda Hospital and Medical College of X")
    # U's own name right before a hospital word is part of the hospital's name ("University College London Hospital")
    uname = [("uname", re.compile("(?:" + "|".join(_wb(n) for n in sorted(u_names, key=len, reverse=True) if len(n) >= 4)
                                   + r") (?:hospitals?|clinics?)\b", re.I))] \
        if any(len(n) >= 4 for n in u_names) else []
    hosp = HOSP_RE
    if us:  # US "X University Medical Center" is the academic medical center (judged 26 Oct): hospitals and clinics only
        hosp = [(k, re.compile(rx.pattern.split("|\\buniversit\\w* (?:medical")[0], re.I)) if k == "univ" else (k, rx) for k, rx in HOSP_RE]
    for kind, rx in uname + hosp:
        if any(rx.search(un) for un in u_names):
            continue  # U's own name is a hospital-like phrase ("... Health Science Center"): never mask it
        t2 = rx.sub(" | ", t)
        if t2 == t:
            continue
        t = t2
        if _keep(t.lower(), u_names, u_acr, desc_names, core, t, distinct, city) is None:
            return "drop:hosp_" + kind
    return "keep:" + _keep(t.lower(), u_names, u_acr, desc_names, core, t, distinct, city)



return names_u(s, u_names, u_acr, desc_names, mask_names, u_places)
$$;

CREATE OR REPLACE TABLE openalex.institutions.affiliation_related_org_guard_today AS
WITH inst AS (SELECT id, type, lineage FROM openalex.institutions.institutions_api),
ai AS (SELECT i.id AS a_id, CAST(regexp_extract(x.id, 'I([0-9]+)$', 1) AS BIGINT) AS b_id, x.relationship AS rel
       FROM openalex.institutions.institutions_api i LATERAL VIEW explode(i.associated_institutions) t AS x),
relp AS (SELECT a_id AS u_id, b_id AS h_id FROM ai WHERE rel = 'related' UNION SELECT b_id, a_id FROM ai WHERE rel = 'related'),
pc AS (SELECT a_id, b_id FROM ai WHERE rel IN ('parent', 'child')),
rel AS (SELECT r.u_id, r.h_id, h.type AS h_type FROM relp r
        JOIN inst u ON u.id = r.u_id AND u.type = 'education' JOIN inst h ON h.id = r.h_id
        LEFT ANTI JOIN pc ON (pc.a_id = r.u_id AND pc.b_id = r.h_id) OR (pc.a_id = r.h_id AND pc.b_id = r.u_id)
        WHERE NOT array_contains(h.lineage, concat('https://openalex.org/I', r.u_id))
          AND NOT array_contains(u.lineage, concat('https://openalex.org/I', r.h_id))),
a AS (SELECT raw_affiliation_string AS s, institution_ids AS ids, countries FROM openalex.institutions.affiliation_matcher_answers
      WHERE run_at >= current_timestamp() - INTERVAL 3 DAYS AND size(institution_ids) >= 2),
c AS (SELECT a.s, a.ids, rel.u_id, collect_set(rel.h_type) AS h_types
      FROM (SELECT s, ids, explode(ids) AS iid FROM a) a JOIN rel ON rel.u_id = a.iid WHERE array_contains(a.ids, rel.h_id)
      GROUP BY a.s, a.ids, rel.u_id),
nm0 AS (SELECT id, norm, kind FROM openalex.institutions.oxjob1395_names_v1),
live AS (SELECT i.id, lower(n) AS norm, k AS kind FROM openalex.institutions.institutions_api i
         LATERAL VIEW explode(array_union(array(i.display_name), coalesce(i.display_name_alternatives, array()))) t1 AS n
         LATERAL VIEW explode(array('alt')) t2 AS k WHERE i.id NOT IN (SELECT DISTINCT id FROM nm0)
         UNION ALL SELECT i.id, lower(n), 'acronym' FROM openalex.institutions.institutions_api i
         LATERAL VIEW explode(coalesce(i.display_name_acronyms, array())) t AS n WHERE i.id NOT IN (SELECT DISTINCT id FROM nm0)),
nm AS (SELECT id, collect_set(CASE WHEN kind <> 'acronym' THEN norm END) AS names, collect_set(CASE WHEN kind = 'acronym' THEN norm END) AS acr
       FROM (SELECT * FROM nm0 UNION ALL SELECT * FROM live) GROUP BY id),
dsc AS (SELECT DISTINCT CAST(regexp_extract(l, 'I([0-9]+)$', 1) AS BIGINT) AS anc, i.id AS d
        FROM openalex.institutions.institutions_api i LATERAL VIEW explode(i.lineage) t AS l),
dn AS (SELECT x.anc AS u_id, slice(collect_set(n.norm), 1, 400) AS desc_names
       FROM (SELECT * FROM dsc WHERE anc <> d AND anc IN (SELECT DISTINCT u_id FROM c)) x
       JOIN nm0 n ON n.id = x.d AND n.kind <> 'acronym' GROUP BY 1),
o AS (SELECT q.s, q.u_id, flatten(collect_list(concat(coalesce(nm.names, array()), coalesce(nm.acr, array())))) AS mask_names
      FROM (SELECT s, u_id, explode(ids) AS oid FROM c) q
      LEFT ANTI JOIN (SELECT * FROM dsc WHERE anc <> d) d2 ON d2.anc = q.u_id AND d2.d = q.oid
      JOIN nm ON nm.id = q.oid WHERE q.oid <> q.u_id GROUP BY 1, 2),
cur AS (SELECT raw_affiliation_string, curated_add_ids FROM openalex.institutions.raw_affiliation_strings_institutions_mv WHERE size(curated_add_ids) > 0),
pat AS (SELECT raw_affiliation_string, flatten(collect_list(add_ids)) AS patch_adds FROM openalex.institutions.oxjob1395_patches GROUP BY 1),
v AS (SELECT c.s, c.u_id, c.h_types,
             openalex.institutions.affiliation_names_u(c.s, nm.names, nm.acr, coalesce(dn.desc_names, array()), coalesce(o.mask_names, array()),
                 array(ui.geo.city, ui.geo.region, ui.geo.country)) AS verdict
      FROM c JOIN nm ON nm.id = c.u_id AND size(nm.names) > 0
      LEFT JOIN openalex.institutions.institutions_api ui ON ui.id = c.u_id
      LEFT JOIN dn ON dn.u_id = c.u_id LEFT JOIN o ON o.s = c.s AND o.u_id = c.u_id
      LEFT JOIN cur ON cur.raw_affiliation_string = c.s LEFT JOIN pat ON pat.raw_affiliation_string = c.s
      WHERE NOT coalesce(array_contains(cur.curated_add_ids, c.u_id), false) AND NOT coalesce(array_contains(pat.patch_adds, c.u_id), false)
        AND size(array_except(c.h_types, array('education'))) > 0),
k AS (SELECT s, collect_set(u_id) AS remove_ids, array_join(array_sort(collect_set(substring(verdict, 6))), '+') AS cls
      FROM v WHERE verdict IN ('drop:inside_linked', 'drop:hosp_univ', 'drop:hosp_uname', 'drop:hosp_dutch') GROUP BY s),
b AS (SELECT a.s, k.remove_ids, k.cls, a.ids AS before_ids, a.countries AS before_countries,
             filter(a.ids, x -> NOT array_contains(k.remove_ids, x)) AS after_ids FROM a JOIN k ON k.s = a.s),
cc AS (SELECT b.s, collect_set(i.country_code) AS cc FROM (SELECT s, explode(after_ids) AS id FROM b) b
       JOIN openalex.institutions.institutions_api i ON i.id = b.id WHERE i.country_code IS NOT NULL GROUP BY 1)
SELECT b.s AS raw_affiliation_string, xxhash64(b.s) AS sid, concat('related_org_daily:', b.cls) AS basis, b.remove_ids,
       b.before_ids, b.before_countries, b.after_ids,
       CASE WHEN size(b.after_ids) = 0 THEN array() ELSE coalesce(cc.cc, array()) END AS after_countries
FROM b LEFT JOIN cc ON cc.s = b.s;

SELECT CASE WHEN COUNT(*) > 20000 THEN RAISE_ERROR(concat('related-org guard: ', COUNT(*), ' strings today, over the 20,000 cap; check before writing (oxjob #1832)')) END AS cap_check,
       COUNT(*) AS strings FROM openalex.institutions.affiliation_related_org_guard_today;

MERGE INTO openalex.institutions.affiliation_matcher_answers t USING openalex.institutions.affiliation_related_org_guard_today r ON t.raw_affiliation_string = r.raw_affiliation_string
WHEN MATCHED AND t.institution_ids <=> r.before_ids THEN UPDATE SET t.institution_ids = r.after_ids, t.countries = r.after_countries;

INSERT INTO openalex.institutions.oxjob1395_patches
SELECT 7, 'related_org_drop_1832', current_timestamp(), r.raw_affiliation_string, r.sid, r.basis, CAST(array() AS ARRAY<BIGINT>),
       r.remove_ids, r.before_ids, r.before_countries, r.after_ids, r.after_countries
FROM openalex.institutions.affiliation_related_org_guard_today r JOIN openalex.institutions.affiliation_matcher_answers a ON a.raw_affiliation_string = r.raw_affiliation_string
WHERE a.institution_ids <=> r.after_ids;
